mapper.select:
SELECT id, type, title, body, reference_id, is_read, created_at
FROM notifications
WHERE type = #{type}
ORDER BY created_at DESC
LIMIT #{size} OFFSET #{offset}

SELECT id, user_id, type, title, body, reference_id, is_read, created_at
FROM notifications
WHERE user_id = #{userId}
ORDER BY created_at DESC
LIMIT #{size} OFFSET #{offset}
